function go(page,id){state.page=page;state.detail=id||'';save();render();window.scrollTo(0,0)}function button(text,act,cls='btn'){return `<button class="${cls}" data-act="${esc(act)}">${text}</button>`}function badge(t,c=''){return `<span class="badge ${c}">${t}</span>`}function head(title,sub='',right=''){return `<div class="page-head"><div><div class="eyebrow">DAKSHYA · ${state.role}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}function card(title,body,extra=''){return `<section class="card ${extra}"><h3>${title}</h3>${body}</section>`}function progressRow(n,p){return `<div class="progress-row"><span>${n}</span><b>${p}%</b></div><div class="progress"><span style="width:${p}%"></span></div>`}
function shell(content){let nav=navMap[state.role]||navMap.Trainee;return `<div class="app ${state.theme==='dark'?'dark':''} ${state.textSize==='large'?'scale-large':state.textSize==='small'?'scale-small':''}"><aside class="sidebar"><div class="brand"><strong>DAKSHYA</strong><small>Cooperative Learning & Employment</small></div><nav class="nav"><div class="nav-label">Workspace</div>${nav.map(n=>`<button data-page="${navPage[n]}" class="${state.page===navPage[n]?'active':''}"><span class="ico">${icon[n]||'·'}</span>${n}</button>`).join('')}</nav><div class="sidefoot"><div class="user-mini"><div class="avatar">${state.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div>${esc(state.name)}<small>${state.role}</small></div></div><select id="role-switch">${roles.map(r=>`<option ${r===state.role?'selected':''}>${r}</option>`)}</select></div></aside><main class="main"><header class="topbar"><div class="crumb">${pageTitle()}</div><div class="search"><input id="global-search" placeholder="Search courses, jobs, people…" value="${esc(state.query||'')}"></div><button class="top-action" title="Connection status" data-act="sync-panel">${state.offline?'◉':'●'}</button><button class="top-action" title="Notifications" data-page="notifications">♧${state.notifications?`<sup>${state.notifications}</sup>`:''}</button><button class="top-action" title="Settings" data-page="settings">⚙</button><button class="top-action" title="Profile" data-page="profile">◉</button></header>${state.offline?`<div class="offline-banner">● Offline Mode · Local training services active <button class="linkbtn" data-act="hub-sync">Sync when online</button></div>`:''}<div class="container">${content}</div></main><div class="mobilebar">${[['dashboard','⌂','Home'],['learning','▷','Learn'],['passport','◇','Skills'],['jobs','⌕','Jobs'],['profile','○','Profile']].map(([p,i,n])=>`<button data-page="${p}" class="${state.page===p?'active':''}"><b>${i}</b>${n}</button>`).join('')}</div></div>`}
function pageTitle(){const n=Object.keys(navPage).find(k=>navPage[k]===state.page);return state.detail?`${n||'Details'} · ${state.detail}`:n||'Welcome'}
function dashboard(){
if(state.role==='Trainer')return head('Trainer overview','PACS Digital Operations · Batch 07')+'<div class="grid g4">'+[['Active batches','3'],['Learners','30'],['Attendance','91%'],['Pending assessments','8']].map(x=>'<div class="card"><div class="stat">'+x[1]+'</div><div class="stat-label">'+x[0]+'</div></div>').join('')+'</div>'+card('Batch 07 · PACS Digital Operations','30 learners · 91% attendance · Average assessment 76% '+button('Mark Attendance','scan-attendance','btn'));
if(state.role==='Institute Admin')return head('Institute overview','VAMNICOM, Pune')+'<div class="grid g4">'+[['Active programmes','12'],['Upcoming batches','6'],['Learners','486'],['Trainers','28']].map(x=>'<div class="card"><div class="stat">'+x[1]+'</div><div class="stat-label">'+x[0]+'</div></div>').join('')+'</div>'+card('Operations',button('Manage programmes','programmes','btn')+button('Create batch','create-batch','btn'));
if(state.role==='NCCT Admin')return head('National training overview','NCCT FY 2024–25 context · Demo metrics',badge('DEMO DATA','amber'))+'<div class="grid g4">'+[['Participants','315,474'],['Programmes','4,389'],['Institutes','20'],['Platform learners','12,840']].map(x=>'<div class="card"><div class="stat">'+x[1]+'</div><div class="stat-label">'+x[0]+'</div></div>').join('')+'</div>'+card('Monitoring',button('Analytics','analytics','btn')+button('Training Hubs','hub','btn'));
if(state.role==='Employer')return head('Employer dashboard','Aarohan Co-op Services · Demo employer',button('+ Create job','create-job','btn primary'))+'<div class="grid g4">'+[['Active jobs','4'],['Candidates','128'],['Applications','16'],['Shortlisted',String((state.shortlisted||[]).length)]].map(x=>'<div class="card"><div class="stat">'+x[1]+'</div><div class="stat-label">'+x[0]+'</div></div>').join('')+'</div>'+card('Recent applicants','Rahul Sharma · Pune · PACS ERP · 92% match '+button('View profile','view-candidate','btn'));
return head('Good morning, Rahul','Continue your learning journey. Your next step is ready.',button('Continue Learning →','course-pacs','btn primary'))+'<div class="grid g4">'+[['Learning progress','68%'],['Attendance','92%'],['Certificates','3'],['Job matches','4']].map(x=>'<div class="card"><div class="stat">'+x[1]+'</div><div class="stat-label">'+x[0]+'</div></div>').join('')+'</div><div class="grid g2" style="margin-top:16px">'+card('PACS Digital Operations',progressRow('Course progress',state.progress)+button('Open course','course-pacs','btn'))+card('Recommended next step','Cooperative Accounting · Based on your 44% assessment '+button('View learning path','skills','btn'))+'</div>'+card('Your skill growth',skills.slice(0,3).map(s=>progressRow(...s)).join(''));
}function catalogue(){let q=(state.query||'').toLowerCase();let list=programmes.filter(p=>`${p.title} ${p.cat} ${p.institute} ${p.mode}`.toLowerCase().includes(q));return `${head('Programmes','Explore practical training from cooperative institutions.',`${state.role==='Institute Admin'?button('+ Create programme','create-programme','btn primary'):''} ${button('My learning →','learning','btn')}`)}<div class="filters"><input id="catalog-search" placeholder="Search programmes" value="${esc(state.query||'')}"><select id="mode-filter"><option value="">All modes</option><option>Online</option><option>Hybrid</option><option>Centre</option></select><select id="category-filter"><option value="">All categories</option>${[...new Set(programmes.map(p=>p.cat))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="grid g3">${list.map(p=>programmeCard(p)).join('')}</div>`}
function programmeCard(p){let enrolled=state.enrolled.includes(p.id);return `<article class="card course-card"><div>${badge(p.cat)} <span class="small muted">${p.duration}</span></div><h3>${p.title}</h3><div class="meta">${p.institute}<br>${p.mode} · ${p.level}<br>${p.lang}</div>${enrolled?progressRow('Your progress',state.progress):''}<div class="bottom"><span class="small muted">${p.seats} seats available</span>${button(enrolled?'Continue →':'View programme →',`programme-${p.id}`,'btn smallbtn '+(enrolled?'primary':''))}</div></article>`}
function programmeDetail(){let p=programmes.find(x=>x.id===(state.detail||'pacs'))||programmes[0],enrolled=state.enrolled.includes(p.id);return `${head(p.title,`${p.institute} · ${p.duration} · ${p.mode}`,button('← All programmes','programmes','btn'))}<div class="grid g2"><section class="card"><div class="card-head"><h3>Programme overview</h3>${badge(p.level)}</div><p class="small muted" style="line-height:1.8">${p.desc}</p><div class="grid g2 small"><div><b>Trainer</b><p class="muted">${p.trainer}</p></div><div><b>Next cohort</b><p class="muted">${p.date}</p></div><div><b>Language</b><p class="muted">${p.lang}</p></div><div><b>Seats available</b><p class="muted">${p.seats}</p></div></div><div class="filters">${button(enrolled?'Continue Learning':'Enroll',enrolled?'course-'+p.id:`enroll-${p.id}`,'btn primary')}${button('Download Offline',`download-${p.id}`,'btn')}${button('Ask Career Assistant','assistant','btn')}</div></section><section class="card"><h3>Learning outcomes</h3><ul class="small muted" style="line-height:2"><li>Apply digital workflows in a cooperative setting</li><li>Maintain accurate member and transaction records</li><li>Understand responsible governance practices</li></ul><h3 style="margin-top:20px">Assessment & certification</h3><p class="small muted">Module quizzes and a final applied assessment. Learners who meet the pass mark receive a verified DAKSHYA credential.</p></section></div><section class="card" style="margin-top:16px"><h3>Curriculum</h3>${p.modules.map((m,i)=>`<div style="padding:12px 0;border-bottom:1px solid var(--line);font-size:12px"><b>${String(i+1).padStart(2,'0')} · ${m}</b><span class="muted" style="float:right">${i===1?'Video · 35 min':'Reading · 20 min'}</span></div>`).join('')}</section>`}
function learning(){return `${head('My Learning','Pick up where you left off.')}<div class="grid g3">${state.enrolled.map(id=>programmeCard(programmes.find(p=>p.id===id)||programmes[0])).join('')||'<div class="card">No programmes yet. Explore the catalogue to get started.</div>'}</div><h3 style="margin-top:25px">Recommended for you</h3><div class="grid g3">${programmeCard(programmes[1])}${programmeCard(programmes[2])}</div>`}
function course(){let p=programmes.find(x=>`course-${x.id}`===(state.detail||'course-pacs'))||programmes[0],done=state.completed.includes(p.id+'-2');return `${head(p.title,'Course player · your progress is saved automatically.',button('← My learning','learning','btn'))}<div class="course-layout"><section class="card module-list"><h3>Course modules</h3>${p.modules.map((m,i)=>`<button class="${i===2?'active':''}" data-act="lesson-${i}">${i<2?'✓':i+1+'.'} ${m}</button>`).join('')}</section><section class="card"><div class="lesson-stage"><div><div class="play">▶</div><b>Lesson preview</b><p class="small muted">Course content is available online and in your offline package.</p></div></div><div style="padding:18px 2px"><div class="eyebrow">MODULE 3 · READING</div><h2 style="font:700 20px Manrope">ERP Fundamentals</h2><p class="small muted" style="line-height:1.8">Explore how member records, deposits, loans and reports connect through a cooperative ERP. This learning unit uses a practical PACS workflow to help you understand everyday digital operations.</p><div class="filters">${button('← Previous','lesson-1','btn')}${button(done?'Completed ✓':'Mark Complete',`complete-${p.id}`,'btn primary')}${button('Next lesson →','lesson-3','btn')}</div></div></section><section class="card"><h3>Course progress</h3>${progressRow('Completed',state.progress)}<h3 style="margin-top:23px">Lesson resources</h3><p class="small muted">ERP workflow guide · PDF</p>${button('Download resource','download-'+p.id,'btn smallbtn')}<h3 style="margin-top:23px">Your notes</h3><textarea id="lesson-notes" placeholder="Add a private note…" style="width:100%;height:85px;border:1px solid var(--line);padding:9px;border-radius:6px">${esc(localStorage.getItem('dakshya-notes')||'')}</textarea></section></div>`}
function skillsPage(){return `${head('AI Skill Insights','Assessment signals and learning history inform these suggestions.') }<div class="grid g2"><section class="card"><h3>Current skill profile</h3>${skills.map(s=>progressRow(...s)).join('')}</section><section class="card recommend"><div class="eyebrow">HIGH PRIORITY · BASED ON YOUR ASSESSMENT</div><h2 style="font:700 21px Manrope">Cooperative Accounting</h2><p class="small muted">Recent assessment indicates weakness in ledger handling and cooperative financial statements.</p><h3 style="margin-top:23px">Recommended learning path</h3>${['Cooperative Accounting Basics','PACS Financial Records','Financial Reporting','Audit & Compliance'].map((x,i)=>`<div style="padding:9px 0;border-bottom:1px solid var(--line);font-size:12px">${i+1}. ${x}</div>`).join('')}${button('Start recommended path →','start-path','btn primary')}
<p class="small muted">Recommendation is a demo simulation based on your assessment.</p></section></div><section class="card" style="margin-top:16px"><h3>How these insights work</h3><p class="small muted">Assessment → competency signal → recommended learning → verified skill update. Your current Accounting score of 44% highlights a focused area to improve.</p></section>`}
function passport(){return `${head('Skill Passport','Your verified learning and competency profile.',button('Share Passport','share-passport','btn primary'))}<div class="passport"><div class="passport-head"><div class="avatar">RS</div><div style="flex:1"><h2 style="font:700 20px Manrope;margin:0">Rahul Sharma</h2><div class="small muted">Trainee · Pune, Maharashtra · Passport ID ${state.skillPassportId}</div></div>${badge('✓ VERIFIED')}</div><div class="grid g2" style="padding:22px 0"><div><h3>Your verified competencies</h3>${skills.slice(0,4).map(s=>progressRow(...s)).join('')}</div><div><h3>Employment readiness</h3><div class="stat">82%</div><div class="small muted">Profile completeness · 4 matched roles</div><div style="margin-top:18px">${badge('5 VERIFIED SKILLS')}&nbsp; ${badge('3 CERTIFICATIONS')}</div><p class="small muted" style="line-height:1.7">${state.visibility?'Your Skill Passport is shareable. Only selected information is public.':'Your Skill Passport is private.'}</p></div></div><h3>Verified certifications</h3><div class="grid g3">${certificates.map(c=>`<div class="credential"><div style="display:flex;justify-content:space-between"><div>${badge('✓ VERIFIED')}<h3 style="margin:12px 0 5px">${c[0]}</h3><div class="small muted">${c[1]} · ${c[2]}</div><div class="small muted" style="margin-top:8px">${c[3]}</div></div><div class="qr" aria-label="QR representation"></div></div></div>`).join('')}</div><h3 style="margin-top:24px">Learning history</h3><div class="timeline"><div class="timeline-item"><b>PACS Digital Operations</b><div class="small muted">Completed modules 1–2 · Aug 2026</div></div><div class="timeline-item"><b>Digital Literacy for Cooperative Personnel</b><div class="small muted">Credential earned · Jun 2026</div></div><div class="timeline-item"><b>Cooperative Member Services</b><div class="small muted">Credential earned · Apr 2026</div></div></div></div>`}
function jobsPage(){let q=(state.query||'').toLowerCase();let list=jobs.filter(j=>`${j.title} ${j.location} ${j.skills.join(' ')}`.toLowerCase().includes(q));return `${head(state.role==='Employer'?'Job management':'Cooperative-sector jobs',state.role==='Employer'?'Create roles and find verified candidates.':'Matched opportunities based on your verified skills.',button(state.role==='Employer'?'+ Create job':'My applications →',state.role==='Employer'?'create-job':'applications','btn primary'))}<div class="filters"><input id="job-search" placeholder="Search title, skill, or location" value="${esc(state.query||'')}"><select id="job-location"><option value="">All locations</option>${[...new Set(jobs.map(x=>x.location))].map(x=>`<option>${x}</option>`).join('')}</select><select><option>Sort: relevance</option><option>Newest</option><option>Location</option></select></div><div class="grid g2">${list.map(jobCard).join('')}</div>`}
function jobCard(j){return `<article class="card"><div class="card-head"><div>${badge(`${j.match}% MATCH`,'blue')} <span class="small muted">Platform-generated demo score</span></div><button class="linkbtn" data-act="save-${j.id}">${state.saved.includes(j.id)?'♥ Saved':'♡ Save'}</button></div><h3>${j.title}</h3><p class="small muted">${j.company} · ${j.location} · ${j.salary}</p><div>${j.skills.map(s=>badge(s,'gray')).join(' ')}</div><p class="small muted" style="line-height:1.7">${j.desc}</p><div class="small"><b>Why this match?</b> ✓ ${j.skills.slice(0,2).join(' · ')} · △ ${j.missing}</div><div style="margin-top:15px">${button('View opportunity →',`job-${j.id}`,'btn primary smallbtn')}</div></article>`}
function jobDetail(){let j=jobs.find(x=>`job-${x.id}`===(state.detail||''))||jobs[0];return `${head(j.title,`${j.company} · ${j.location}`,button('← Jobs','jobs','btn'))}<div class="grid g2"><section class="card"><h3>Role overview</h3><p class="small muted">${j.desc}</p><div class="grid g2 small"><p><b>Salary</b><br>${j.salary}</p><p><b>Experience</b><br>${j.experience}</p><p><b>Job type</b><br>${j.type}</p><p><b>Location</b><br>${j.location}</p></div><h3>Skills & responsibilities</h3><p>${j.skills.map(s=>badge(s,'gray')).join(' ')}</p><p class="small muted">Maintain accurate cooperative records, support member services, prepare routine reports and coordinate digital workflows with society teams.</p>${button(state.applications.includes(j.id)?'Application submitted ✓':'Apply for this role',`apply-${j.id}`,'btn primary')}</section><section class="card recommend"><h3>Why this matches you</h3><div class="stat">${j.match}%</div><div class="small muted">Platform-generated match for this demo</div>${j.skills.map(s=>`<p class="small">✓ ${s}</p>`).join('')}<p class="small">△ ${j.missing} · a useful area to strengthen</p><p class="small muted">Your verified PACS ERP and Digital Literacy skills contribute to this match.</p></section></div>`}
function certificatesPage(){return `${head('Certificates','Your learning credentials in one place.',button('Verify a credential →','verify','btn'))}<div class="grid g3">${certificates.map(c=>`<div class="card"><div class="card-head">${badge('✓ VERIFIED')}<div class="qr"></div></div><h3>${c[0]}</h3><p class="small muted">${c[1]}<br>Rahul Sharma · Issued ${c[2]}</p><div class="small muted">Credential ID<br><b>${c[3]}</b></div><div class="filters" style="margin:13px 0 0">${button('View','cert-'+c[3],'btn smallbtn')}${button('Share','share-cert','btn smallbtn')}${button('Download','download-cert','btn smallbtn')}</div></div>`).join('')}</div>`}
function attendance(){let isManager=state.role!=='Trainee';return `${head('Attendance',isManager?'Batch attendance and session records.':'Your attendance record for active programmes.',button(isManager?'Scan attendance':'Export CSV',isManager?'scan-attendance':'export-attendance','btn primary'))}<div class="grid g4">${[['Attendance rate',state.attendance+'%'],['Present','23'],['Absent','2'],['Late','1']].map(([n,v])=>`<div class="card"><div class="stat">${v}</div><div class="stat-label">${n}</div></div>`).join('')}</div><section class="card" style="margin-top:16px"><div class="card-head"><h3>Recent sessions</h3><div class="filters"><select><option>All batches</option><option>Batch 07</option></select><input type="date" value="2026-10-05"><select><option>All statuses</option><option>Present</option><option>Absent</option></select></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Programme</th><th>Session</th><th>Status</th><th>Mode</th></tr></thead><tbody>${[['Oct 04, 2026','PACS Digital Operations','ERP workflows','Present','Centre'],['Oct 02, 2026','PACS Digital Operations','Member records','Present','Online'],['Sep 30, 2026','PACS Digital Operations','Digital services','Present','Centre'],['Sep 28, 2026','PACS Digital Operations','PACS overview','Absent','Centre']].map(r=>`<tr>${r.map((x,i)=>`<td>${i===3?badge(x,x==='Present'?'':'amber'):x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`}
function assessments(){return `${head('Assessments','Check your understanding and see focused recommendations.')}<div class="grid g2"><section class="card"><h3>Upcoming</h3><div style="padding:14px 0;border-bottom:1px solid var(--line)"><b>Cooperative Accounting</b><p class="small muted">Tomorrow · 30 minutes · 10 questions · 1 attempt</p>${button('Start assessment →','take-assessment','btn primary smallbtn')}</div><div style="padding:14px 0"><b>Governance & Compliance</b><p class="small muted">Oct 12 · 25 minutes · 8 questions</p>${badge('UPCOMING','amber')}</div></section><section class="card"><h3>Completed results</h3>${[['Cooperative Accounting','44%','Needs Improvement'],['PACS ERP','82%','Strong'],['Digital Literacy','91%','Strong']].map(x=>`<div style="padding:12px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between"><span><b>${x[0]}</b><div class="small muted">${x[2]}</div></span><b>${x[1]}</b></div>`).join('')}</section></div>`}
function takeAssessment(){return `${head('Cooperative Accounting · Assessment','10 questions · 30 minutes',button('← Assessments','assessments','btn'))}<section class="card"><div class="card-head"><div><div class="eyebrow">QUESTION 1 OF 3 · 28:42 REMAINING</div><h2 style="font:700 20px Manrope">Which record is used to track individual member transactions?</h2></div>${badge('1 / 3','blue')}</div>${['Cash book','Member ledger','Minutes register','Attendance sheet'].map((x,i)=>`<label style="display:block;padding:13px;border:1px solid var(--line);border-radius:6px;margin:9px 0;font-size:12px"><input type="radio" name="answer" value="${i}"> &nbsp;${x}</label>`).join('')}<div class="filters" style="margin-top:20px">${button('Mark for review','review-question','btn')}${button('Next question →','next-question','btn')}${button('Submit assessment','submit-assessment','btn primary')}</div></section>`}
function verify(){return `${head('Verify DAKSHYA Credential','Credential verification is public and displays only information needed to verify.') }<section class="card" style="max-width:700px"><h3>Enter Certificate ID</h3><div class="filters"><input id="cert-id" style="flex:1" placeholder="DAKSHYA-COOP-2026-001284" value="${esc(state.verifyId||'')}">${button('Verify Certificate','verify-cert','btn primary')}${button('Scan QR','scan-qr','btn')}</div><div id="verification-result">${state.verifyId?verifyResult(state.verifyId):''}</div></section>`}
function verifyResult(id){let c=certificates.find(x=>x[3]===id);return c?`<div class="card" style="margin-top:18px;background:#f6faf6"><div class="eyebrow">✓ VERIFIED CREDENTIAL</div><h2 style="font:700 20px Manrope">${c[0]}</h2><p class="small muted">Learner: Rahul Sharma<br>Issuing institute: ${c[1]}<br>Issue date: ${c[2]}<br>Credential ID: ${c[3]}</p>${badge('VERIFIED')}</div>`:`<div class="card" style="margin-top:18px"><div class="eyebrow" style="color:var(--danger)">✕ NOT FOUND</div><p class="small muted">No credential matches that ID. Check the ID and try again.</p></div>`}
function career(){return `${head('DAKSHYA Career Assistant','Practical guidance grounded in your assessment and Skill Passport.') }<div class="grid g2"><section class="card chat"><div class="card-head"><h3>✳ DAKSHYA Career Assistant</h3>${badge('DEMO ASSISTANT')}</div><div class="messages" id="messages"><div class="bubble">Hi Rahul. I can help you understand your skills, choose your next course and explore cooperative-sector opportunities.<div style="margin-top:7px">${badge('Based on your Skill Passport','blue')}</div></div>${(state.chat||[]).map(m=>`<div class="bubble ${m[0]==='you'?'me':''}">${esc(m[1])}</div>`).join('')}</div><div>${['What should I learn next?','Which jobs match my skills?','How can I improve my Skill Passport?','What roles can I target with PACS ERP skills?'].map(x=>`<button class="prompt" data-chat="${x}">${x}</button>`).join('')}</div><div class="chat-input"><input id="chat-input" placeholder="Ask about your next step…">${button('Send','send-chat','btn primary')}</div></section><section class="card recommend"><div class="eyebrow">PERSONALIZED TO YOUR PROFILE</div><h3>Suggested next step</h3><b>Cooperative Accounting Basics</b><p class="small muted">Your score of 44% points to ledger handling and financial statements as the best focus.</p>${button('Add to my learning path','start-path','btn soft')}<h3 style="margin-top:28px">Your strengths</h3>${badge('Digital Literacy · 91%')} ${badge('PACS ERP · 82%')}<p class="small muted" style="margin-top:20px">Advice is generated from local demo profile data. No AI service connection required.</p></section></div>`}
function offline(){return `${head('Offline Content','Learning continues locally when a centre connection is unavailable.',button(state.offline?'Go online':'Enable Offline Mode',state.offline?'go-online':'go-offline','btn primary'))}<div class="grid g3"><div class="card"><div class="stat">${state.downloaded.length}</div><div class="stat-label">Downloaded courses</div></div><div class="card"><div class="stat">${state.pending.length}</div><div class="stat-label">Pending sync events</div></div><div class="card"><div class="stat">${state.downloaded.length?'184 MB':'0 MB'}</div><div class="stat-label">Local storage used</div></div></div><section class="card" style="margin-top:16px"><h3>Available course packages</h3>${programmes.map(p=>`<div style="padding:14px 0;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between"><div><b>${p.title}</b><div class="small muted">Course lessons · resources · assessment</div></div>${button(state.downloaded.includes(p.id)?'Available Offline ✓':'Download for Offline',`download-${p.id}`,state.downloaded.includes(p.id)?'btn soft':'btn')}</div>`).join('')}<p class="small muted">Offline activity is stored locally until synchronization.</p></section>`}
function hub(){return `${head('Training Hub','A local training-centre service simulation · Training Centre: Pune',button(state.offline?'Restore Internet':'Simulate Internet Loss',state.offline?'go-online':'go-offline','btn primary'))}<div class="grid g3"><section class="card"><div class="card-head"><h3>Hub status</h3>${badge(state.offline?'OFFLINE':'ONLINE',state.offline?'amber':'')}</div><div class="stat">${state.offline?'Local':'Connected'}</div><p class="small muted">Raspberry Pi 5 / Mini PC · Wi-Fi Access Point</p><p class="small muted">Optional 4G/5G · UPS · QR scanner</p></section><section class="card"><h3>Local services</h3><p class="small">✓ Local LMS</p><p class="small">✓ Local Database</p><p class="small">✓ Local Attendance</p><p class="small">✓ Local Assessment</p></section><section class="card"><h3>Connected devices</h3><div class="stat">18</div><div class="small muted">learners · 2 trainers</div><p class="small muted">Last sync: ${state.lastSync||'Today, 9:14 AM'}</p></section></div><div class="grid g2" style="margin-top:16px"><section class="card"><h3>Training Hub workflows</h3><div class="filters">${button('Start Offline Mode',state.offline?'go-online':'go-offline','btn primary')}${button('Scan Attendance','scan-attendance','btn')}${button('Launch Assessment','take-assessment','btn')}${button('Sync with Cloud','hub-sync','btn')}${button('View Local Courses','offline','btn')}</div></section><section class="card"><h3>Recent sync activity</h3>${state.pending.length?`${state.pending.length} event(s) waiting to sync.`:'Everything is up to date.'}<p class="small muted">Demo simulation · browser is not acting as a Raspberry Pi.</p></section></div>`}
function profile(){return `${head('My Profile','Manage your personal details and employment preferences.',button('Edit profile','edit-profile','btn primary'))}<section class="card"><div class="passport-head"><div class="avatar">RS</div><div><h2 style="margin:0;font:700 20px Manrope">${esc(state.name)}</h2><div class="small muted">${esc(state.email)} · ${esc(state.profile.location)}</div></div></div><div class="grid g3" style="margin-top:22px">${[['Phone',state.profile.phone],['Education',`${state.profile.degree} · ${state.profile.institution}`],['Cooperative',state.profile.organization],['Role',state.profile.coopRole],['Experience',state.profile.experience],['Preferred role',state.profile.preferredRole],['Preferred location',state.profile.preferredLocation],['Availability',state.profile.availability],['Salary range',state.profile.salary]].map(([k,v])=>`<div><div class="small muted">${k}</div><b class="small">${esc(v)}</b></div>`).join('')}</div></section>`}
function settings(){return `${head('Settings','Your preferences apply across this browser.') }<div class="grid g2"><section class="card"><h3>Appearance & language</h3><label class="field">Theme<select id="theme-select"><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option><option value="system">System</option></select></label><label class="field">Language<select id="lang-select">${['English','हिन्दी','मराठी'].map(x=>`<option ${state.language===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Text size<select id="size-select"><option value="normal">Default</option><option value="large" ${state.textSize==='large'?'selected':''}>Large</option><option value="small" ${state.textSize==='small'?'selected':''}>Small</option></select></label><label class="field"><span><input type="checkbox" id="motion" ${state.reducedMotion?'checked':''}> Reduce motion</span></label></section><section class="card"><h3>Privacy & notifications</h3><label class="field"><span><input type="checkbox" id="visibility" ${state.visibility?'checked':''}> Allow public Skill Passport sharing</span></label><label class="field"><span><input type="checkbox" id="employer-visibility" ${state.employerVisibility?'checked':''}> Show selected profile to employers</span></label><label class="field"><span><input type="checkbox" id="notify" ${state.notify!==false?'checked':''}> Learning and application notifications</span></label><p class="small muted">Your Skill Passport only shares information you choose to make public.</p></section></div><section class="card" style="margin-top:16px"><h3>Demo data & local storage</h3><p class="small muted">Clear offline packages or restore the original demo profile on this device.</p><div class="filters">${button('Clear offline data','clear-offline','btn')}${button('Reset demo data','reset-demo','btn danger')}</div></section>`}
function notifications(){return `${head('Notifications','Recent updates from your learning and job journey.',button('Mark all read','read-notifications','btn'))}${[['Programme reminder','Cooperative Accounting assessment is tomorrow at 10:30 AM.','Today · 8:15 AM'],['New matched opportunity','Cooperative ERP Executive · Pune · 92% match','Yesterday'],['Certificate verified','Your PACS Digital Operations credential is verified.','Aug 18, 2026']].map(x=>`<div class="card" style="margin-bottom:10px"><b>${x[0]}</b><p class="small muted">${x[1]}</p><span class="small muted">${x[2]}</span></div>`).join('')}`}
function analytics(){return `${head(state.role==='NCCT Admin'?'National overview':'Institute analytics','Demo platform metrics · illustrative values for product demonstration.',badge('DEMO DATA','amber'))}<div class="grid g4">${[['Participants','315,474','NCCT FY 2024–25 context'],['Programmes','4,389','NCCT FY 2024–25 context'],['Institutes','20','Constituent institutes'],['Active learners','12,840','Current platform demo']].map(([a,b,c])=>`<div class="card"><div class="stat">${b}</div><div class="stat-label">${a}</div><div class="small muted" style="margin-top:8px">${c}</div></div>`).join('')}</div><div class="grid g2" style="margin-top:16px">${card('Programme completion',`<div class="skill-line"><label>Digital Operations</label><div class="progress"><span style="width:78%"></span></div><b>78%</b></div><div class="skill-line"><label>Cooperative Finance</label><div class="progress"><span style="width:69%"></span></div><b>69%</b></div><div class="skill-line"><label>Governance</label><div class="progress"><span style="width:84%"></span></div><b>84%</b></div>`)}${card('Employment outcomes',`<div class="stat">68%</div><div class="stat-label">Learners with reported placement or progression · demo</div><p class="small muted">Skill gaps most frequently reported: Cooperative Accounting, Digital Member Services.</p>`)}</div>`}
function generic(){let page=state.page;if(['dashboard',''].includes(page))return dashboard();if(page==='programmes')return catalogue();if(page==='programme')return programmeDetail();if(page==='learning')return learning();if(page==='course')return course();if(page==='skills')return skillsPage();if(page==='passport')return passport();if(page==='jobs')return jobsPage();if(page==='job')return jobDetail();if(page==='certificates')return certificatesPage();if(page==='attendance')return attendance();if(page==='assessments')return assessments();if(page==='take-assessment')return takeAssessment();if(page==='verify')return verify();if(page==='assistant')return career();if(page==='offline')return offline();if(page==='hub')return hub();if(page==='profile')return profile();if(page==='settings')return settings();if(page==='notifications')return notifications();if(page==='analytics'||page==='institutes'||page==='employment')return analytics();if(page==='applications')return `${head('My applications','Track your submitted applications.')}${state.applications.length?state.applications.map(id=>jobCard(jobs.find(j=>j.id===id))).join(''):'<section class="card">No applications yet. Explore matched roles to apply.</section>'}`;if(page==='candidates'||page==='learners'||page==='batches'||page==='trainers')return managerPage(page);if(page==='timetable'||page==='hostel'||page==='logistics')return `${head(page[0].toUpperCase()+page.slice(1),'Institute operations and schedules.')}${card(page==='timetable'?'Upcoming sessions':page==='hostel'?'Hostel occupancy':'Logistics overview',`<div class="timeline"><div class="timeline-item"><b>PACS Digital Operations · Batch 07</b><div class="small muted">VAMNICOM Pune · Today, 11:00 AM</div></div><div class="timeline-item"><b>Cooperative Accounting Essentials</b><div class="small muted">Tomorrow, 10:30 AM · Room 204</div></div></div>`)}`;if(page==='help')return helpPage();return dashboard()}
function managerPage(p){let title={candidates:'Candidate search',learners:'Learners',batches:'Batch management',trainers:'Trainers'}[p];let people=[['Rahul Sharma','Pune','PACS ERP · Digital Literacy','3','92%'],['Anita Patil','Nashik','Digital Literacy · Marathi','2','86%'],['Suresh Kumar','Jaipur','Accounting · Cooperative Finance','4','79%'],['Meena Devi','Lucknow','Member Services · Governance','2','74%']];return `${head(title,'Search and review cooperative-sector learning profiles.',p==='batches'?button('Create batch','create-batch','btn primary'): '')}<div class="filters"><input id="people-search" placeholder="Search skill, location, name…">${button('Export CSV','export-learners','btn')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Location</th><th>Verified skills</th><th>Certificates</th><th>Match</th><th>Availability</th><th>Actions</th></tr></thead><tbody>${people.map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${badge(x[4],'blue')}</td><td>Immediate</td><td>${button('View profile','view-candidate','linkbtn')}${button('Shortlist','shortlist-candidate','linkbtn')}</td></tr>`).join('')}</tbody></table></div></section>`}
function helpPage(){return `${head('Help & Support','Answers to common questions about the DAKSHYA demo.')}${card('How DAKSHYA works',`<div class="faq"><details open><summary>Can I learn without an internet connection?</summary><p class="small muted">Download course packages first, then enable Offline Mode. Lessons, attendance and assessments remain available locally. Pending activity syncs when you reconnect.</p></details><details><summary>How does my Skill Passport work?</summary><p class="small muted">It brings verified skills and credentials together. You control whether a public share view is enabled in Settings.</p></details><details><summary>How do I verify a certificate?</summary><p class="small muted">Open Certificate Verification and enter a DAKSHYA credential ID. Public verification shows only credential details.</p></details><details><summary>How are job matches calculated?</summary><p class="small muted">Match percentages are illustrative platform-generated demo scores based on skills, language and job requirements.</p></details></div>`)}`}
function landing(){return `<div class="landing"><header class="public-nav"><div class="brand" style="padding:0;border:0;color:var(--green)"><strong>DAKSHYA</strong><small style="color:var(--muted)">Cooperative Learning & Employment Ecosystem</small></div><div>${button('Verify Certificate','public-verify','btn')}${button('Sign in','login','btn primary')}</div></header><section class="landing-hero"><div><div class="eyebrow">SIH 2026 · PROBLEM STATEMENT SIH26087</div><h1>One journey from learning to opportunity.</h1><p>An AI-enabled cooperative training and employment ecosystem connecting learners, trainers, institutions and employers.</p>${button('Explore DAKSHYA','login','btn primary')}${button('View Training Ecosystem','ecosystem','btn')}</div><div class="land-visual"><div style="text-align:center"><div style="font:700 15px Manrope;margin-bottom:18px">DAKSHYA CLOUD · LMS · ERP · AI</div><div class="ecosystem"><div class="eco-node">TRAINING HUB<br>Local / Offline</div><div class="eco-node">WEB / APP<br>Remote access</div></div><div style="margin-top:19px">Skill Passport · Learning · Employment</div></div></div></section><section class="section" id="ecosystem"><div class="eyebrow">A CONNECTED ECOSYSTEM</div><h2>From learning to work, built around the learner.</h2><div class="flow"><span>TRAIN<br>↓</span><span>ASSESS<br>↓</span><span>CERTIFY<br>↓</span><span>SKILL PASSPORT<br>↓</span><span>EMPLOYMENT</span></div><div class="grid g3"><div class="card"><h3>AI Skill Passport</h3><p class="small muted">Verified competencies and focused next-step guidance.</p></div><div class="card"><h3>Offline Training Hub</h3><p class="small muted">Centre learning continues locally and syncs with the cloud.</p></div><div class="card"><h3>Training to employment</h3><p class="small muted">Connect cooperative skills with relevant opportunities.</p></div></div></section><section class="section"><h2>Built for flexible access</h2><p class="muted">Remote web and app · Training centre hub · Offline learning</p>${button('Start your learning journey','login','btn primary')}</section><footer class="section small muted">DAKSHYA · Cooperative Learning & Employment Ecosystem<br>About · Programmes · Verify Certificate · Privacy · Accessibility · Contact<br>SIH 2026 | PS: SIH26087</footer></div>`}
function login(){return `<div class="login-screen"><div class="login-copy"><div class="eyebrow" style="color:#c1d9ca">COOPERATIVE LEARNING & EMPLOYMENT ECOSYSTEM</div><h1>DAKSHYA</h1><p>One journey from learning to opportunity. Connect cooperative learners, trainers, institutions and employers.</p><div class="ecosystem" style="justify-content:flex-start;margin-top:20px"><div class="eco-node">Cloud LMS + ERP</div><div class="eco-node">Training Hub</div><div class="eco-node">Web / App</div></div></div><div class="login-box"><div class="eyebrow">DEMO ACCESS</div><h2 style="font:700 24px Manrope;margin:0">Choose a demo account</h2><p class="small muted">No password required. Your role is saved on this device.</p>${roles.map(r=>`<button class="btn demo-account" data-login="${r}"><span><b>${r} Demo</b><small style="display:block;color:var(--muted);margin-top:3px">${account[r][1]}</small></span><span>→</span></button>`).join('')}${button('Continue as Guest','guest','btn soft')}${button('← Back to DAKSHYA','/','linkbtn')}</div></div>`}
function render(){document.body.classList.toggle('dark',state.theme==='dark');if(state.page==='/'){$('#app').innerHTML=landing();return}if(state.page==='login'){$('#app').innerHTML=login();return}let content;if(state.page==='programme')content=programmeDetail();else if(state.page==='course')content=course();else if(state.page==='job')content=jobDetail();else if(state.page==='take-assessment')content=takeAssessment();else content=generic();$('#app').innerHTML=shell(content)}
function modal(title,body,actions=''){let html=`<div class="modal-bg" id="modal-bg"><div class="modal"><div class="modal-top"><div><h2>${title}</h2><div class="small muted">DAKSHYA demo</div></div><button class="close" data-act="close-modal">×</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</div></div>`;document.body.insertAdjacentHTML('beforeend',html)}
function sync(){if(state.offline){toast('You are offline. Events remain on this device.');return}let n=state.pending.length;state.pending=[];state.lastSync=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});save();render();toast(`${n||4} offline events synced successfully ✓`)}function setOffline(v){state.offline=v;save();render();toast(v?'No Internet · Learning continues locally':'Connection restored · Ready to sync')}
function act(a){if(a==='login'){state.page='login';render();return}if(a==='/'){state.page='/';render();return}if(a==='ecosystem'){document.querySelector('#ecosystem')?.scrollIntoView({behavior:'smooth'});return}if(a==='public-verify'){state.page='verify';render();return}if(['dashboard','programmes','learning','attendance','assessments','certificates','passport','skills','assistant','jobs','offline','notifications','settings','help','batches','learners','trainers','timetable','hub','institutes','analytics','hostel','logistics','employment','candidates','applications','verify','profile'].includes(a)){go(a);return}if(a==='guest'){state.role='Trainee';state.name='Guest Learner';state.page='dashboard';save();render();return}if(a==='sync-panel'){modal('Connection & sync',`<p class="small">Connection <b>${state.offline?'Offline':'Online'}</b></p><p class="small">Last synced <b>${state.lastSync||'Today, 9:14 AM'}</b></p><p class="small">Pending sync <b>${state.pending.length} items</b></p><p class="small">Downloaded content <b>${state.downloaded.length} courses</b></p>`,button('Retry sync','hub-sync','btn primary'));return}if(a==='close-modal'){$('#modal-bg')?.remove();return}if(a==='hub-sync'){sync();return}if(a==='go-offline'){setOffline(true);if(state.role!=='Trainee'&&state.page!=='hub')go('hub');return}if(a==='go-online'){state.offline=false;save();render();sync();return}if(a==='reset-demo'){modal('Reset demo data?',`<p class="small muted">This restores the original learner profile, progress and saved items on this browser.</p>`,button('Cancel','close-modal','btn')+button('Reset demo data now','confirm-reset','btn danger'));return}if(a==='confirm-reset'){localStorage.removeItem('dakshya');localStorage.removeItem('dakshya-notes');state={...initial};$('#modal-bg').remove();render();toast('Demo data restored');return}if(a==='clear-offline'){modal('Clear offline data?',`<p class="small muted">Downloaded course packages and pending local events will be removed.</p>`,button('Cancel','close-modal','btn')+button('Clear data','confirm-clear','btn danger'));return}if(a==='confirm-clear'){state.downloaded=[];state.pending=[];save();$('#modal-bg').remove();render();toast('Offline data cleared');return}if(a==='share-passport'){modal('Share your Skill Passport',`<p class="small muted">Only information you have chosen to make public will appear on the share view.</p><div class="field">Public link<input readonly value="https://dakshya.demo/passport/${state.skillPassportId}"></div>`,button('Close','close-modal','btn')+button('Copy link','copy-passport','btn primary'));return}if(a==='copy-passport'){navigator.clipboard?.writeText(`https://dakshya.demo/passport/${state.skillPassportId}`);$('#modal-bg')?.remove();toast('Passport link copied');return}if(a==='scan-attendance'){modal('Mark Attendance',`<div class="lesson-stage"><div><div class="play">⌗</div><b>Scan trainee QR</b><p class="small muted">Training Centre: Pune · Session: PACS Digital Operations</p>${button('Scan Demo QR','scan-demo-qr','btn primary')} ${button('Face Verification · Optional','face-demo','btn')}</div></div>`);return}if(a==='scan-demo-qr'){state.pending.push({type:'attendance',at:Date.now()});state.attendance=92;save();$('#modal-bg')?.remove();modal('Attendance recorded',`<div class="eyebrow">✓ ATTENDANCE RECORDED</div><h3>Rahul Sharma</h3><p class="small muted">PACS Digital Operations · 09:02 AM</p>${badge('Present')}`);toast('Attendance recorded');return}if(a==='face-demo'){modal('Optional face verification',`<p class="small muted">Camera verification simulated in demo mode. No biometric data is captured or stored.</p>`,button('Done','close-modal','btn primary'));return}if(a==='export-attendance'||a==='export-learners'){let csv='Name,Location,Programme,Attendance\nRahul Sharma,Pune,PACS Digital Operations,Present\nAnita Patil,Nashik,Digital Literacy,Present';download('dakshya-attendance.csv',csv,'text/csv');toast('CSV downloaded');return}if(a==='create-programme'){modal('Create programme',`<form id="programme-form"><label class="field">Programme title<input name="title" required></label><label class="field">Category<input name="cat" required></label><label class="field">Duration<input name="duration" required placeholder="3 weeks"></label><label class="field">Mode<select name="mode"><option>Online</option><option>Hybrid</option><option>Centre</option></select></label><label class="field">Institute<input name="institute" required value="VAMNICOM, Pune"></label><label class="field">Description<textarea name="desc" required></textarea></label></form>`,button('Cancel','close-modal','btn')+button('Create programme','programme-submit','btn primary'));return}if(a==='programme-submit'){let f=$('#programme-form');if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f));programmes.unshift({id:'new'+Date.now(),...d,lang:'English / Hindi',level:'Intermediate',trainer:'Trainer to be assigned',date:'Schedule to be confirmed',seats:30,modules:['Introduction','Core practice','Applied assessment']});$('#modal-bg').remove();render();toast('Programme created');return}if(a.startsWith('programme-')&&a!=='programme-'){let id=a.slice(10);state.page='programme';state.detail=id;render();return}if(a.startsWith('course-')){state.page='course';state.detail=a;render();return}if(a.startsWith('job-')){state.page='job';state.detail=a;render();return}if(a.startsWith('enroll-')){let id=a.slice(7);if(!state.enrolled.includes(id))state.enrolled.push(id);state.notifications++;state.pending.push({type:'enrollment',id});save();render();toast('Programme enrolled successfully');return}if(a.startsWith('download-')){let id=a.slice(9);if(!state.downloaded.includes(id)){toast('Downloading…');setTimeout(()=>{state.downloaded.push(id);save();render();toast('Offline package downloaded ✓')},650)}else toast('Available Offline ✓');return}if(a.startsWith('complete-')){let id=a.slice(9);if(!state.completed.includes(id+'-2')){state.completed.push(id+'-2');state.progress=Math.min(100,state.progress+7);state.pending.push({type:'lesson',id});save();render();toast('Lesson marked complete. Next module unlocked.')}return}if(a==='start-path'){if(!state.enrolled.includes('acct'))state.enrolled.push('acct');save();go('learning');toast('Recommended path added to My Learning');return}if(a.startsWith('save-')){let id=a.slice(5);state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render();toast(state.saved.includes(id)?'Job saved':'Job removed from saved');return}if(a.startsWith('apply-')){let id=a.slice(6);if(!state.applications.includes(id))state.applications.push(id);state.pending.push({type:'application',id});save();render();toast('Application submitted ✓');return}if(a==='verify-cert'){state.verifyId=$('#cert-id').value.trim();save();$('#verification-result').innerHTML=verifyResult(state.verifyId);toast(certificates.some(c=>c[3]===state.verifyId)?'Certificate verified':'Credential not found');return}if(a==='scan-qr'){$('#cert-id').value=certificates[0][3];state.verifyId=certificates[0][3];save();$('#verification-result').innerHTML=verifyResult(state.verifyId);toast('QR scanned in demo mode');return}if(a==='take-assessment'){state.page='take-assessment';render();return}if(a==='submit-assessment'){state.pending.push({type:'assessment'});state.assessed=true;save();go('assessments');toast('Assessment submitted · score 44%');return}if(a==='review-question'||a.startsWith('lesson-')){toast(a==='review-question'?'Question marked for review':'Lesson selected');return}if(a==='next-question'){let radio=$('input[name="answer"]:checked');if(!radio)toast('Choose an answer to continue');else toast('Answer saved · Next question');return}if(a==='send-chat'){sendChat();return}if(a==='edit-profile'){profileModal();return}if(a==='save-profile'){const f=$('#profile-form');if(!f.reportValidity())return;new FormData(f).forEach((v,k)=>state.profile[k]=v);state.name=$('#pname').value;save();$('#modal-bg').remove();render();toast('Profile updated');return}if(a==='go-online'){setOffline(false);return}if(a==='read-notifications'){state.notifications=0;save();render();toast('Notifications marked as read');return}if(a==='create-job'){jobModal();return}if(a==='create-batch'){modal('Create batch',`<label class="field">Batch name<input required placeholder="PACS Digital Operations · Batch 08"></label><label class="field">Programme<select>${programmes.map(p=>`<option>${p.title}</option>`).join('')}</select></label>`,button('Cancel','close-modal','btn')+button('Create batch','close-modal','btn primary'));return}if(a==='view-candidate'){modal('Rahul Sharma · Candidate profile',`<p class="small muted">Pune · 3 verified certificates · Immediate availability</p>${skills.slice(0,3).map(s=>progressRow(...s)).join('')}`,button('Close','close-modal','btn'));return}if(a==='shortlist-candidate'){state.shortlisted=state.shortlisted||[];state.shortlisted.push('Rahul Sharma');save();toast('Rahul Sharma shortlisted');return}if(a==='download-cert'){toast('Certificate PDF prepared for download');return}if(a==='share-cert'){modal('Share credential',`<p class="small muted">Verified credential link ready to share.</p><input readonly style="width:100%;padding:10px" value="https://dakshya.demo/verify?id=${certificates[0][3]}">`,button('Close','close-modal','btn')+button('Copy link','copy-passport','btn primary'));return}if(a.startsWith('cert-')){go('verify');return}if(a==='create-job-submit'){jobSubmit();return}}
function download(name,body,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}function profileModal(){modal('Edit profile',`<form id="profile-form"><label class="field">Full name<input id="pname" required value="${esc(state.name)}"></label><label class="field">Phone<input name="phone" required value="${esc(state.profile.phone)}"></label><label class="field">Location<input name="location" required value="${esc(state.profile.location)}"></label><label class="field">Preferred role<input name="preferredRole" value="${esc(state.profile.preferredRole)}"></label><label class="field">Preferred location<input name="preferredLocation" value="${esc(state.profile.preferredLocation)}"></label><label class="field">Availability<input name="availability" value="${esc(state.profile.availability)}"></label></form>`,button('Cancel','close-modal','btn')+button('Save changes','save-profile','btn primary'))}function jobModal(){modal('Create a job',`<form id="job-form"><label class="field">Job title<input name="title" required></label><label class="field">Location<input name="location" required></label><label class="field">Salary range<input name="salary" required placeholder="₹3–5 LPA"></label><label class="field">Experience<input name="experience" required placeholder="1–3 years"></label><label class="field">Required skills<input name="skills" required placeholder="PACS ERP, Excel"></label><label class="field">Description<textarea name="desc" required></textarea></label></form>`,button('Cancel','close-modal','btn')+button('Publish job','create-job-submit','btn primary'))}function jobSubmit(){let f=$('#job-form');if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f));jobs.unshift({id:'j'+Date.now(),...d,company:'Aarohan Co-op Services (demo employer)',type:'Full-time',match:84,skills:d.skills.split(',').map(x=>x.trim()),missing:'',});$('#modal-bg').remove();render();toast('Job posted successfully')}
function sendChat(){let input=$('#chat-input'),q=input.value.trim();if(!q)return;state.chat=state.chat||[];state.chat.push(['you',q]);let l=q.toLowerCase(),answer=l.includes('job')?'Your PACS ERP (82%), Digital Literacy (91%) and Marathi skills align well with 4 current roles. Cooperative ERP Executive in Pune is your strongest match at 92%.':l.includes('passport')?'Your Skill Passport is 82% complete with 5 verified skills and 3 certificates. Add your preferred role and keep building your Cooperative Accounting competency.':l.includes('role')||l.includes('pacs')?'With PACS ERP and Digital Literacy, consider Cooperative ERP Executive or PACS Digital Operations Assistant roles. Your strongest current match is in Pune.':'Your strongest areas are Digital Literacy and PACS ERP. Your biggest gap is Cooperative Accounting (44%). I recommend Cooperative Accounting Basics followed by PACS Financial Records.';state.chat.push(['bot',answer]);save();render();$('#messages')?.scrollTo(0,9999)}
document.addEventListener('click',e=>{let b=e.target.closest('[data-act],[data-page],[data-login],[data-chat]');if(!b)return;if(b.dataset.page){go(b.dataset.page);return}if(b.dataset.login){state.role=b.dataset.login;state.name=account[state.role][0];state.email=account[state.role][1];state.page='dashboard';save();render();return}if(b.dataset.chat){$('#chat-input').value=b.dataset.chat;sendChat();return}act(b.dataset.act)});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='role-switch'){state.role=t.value;state.name=account[state.role][0];state.email=account[state.role][1];state.page='dashboard';save();render()}if(t.id==='theme-select'){state.theme=t.value==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t.value;save();render()}if(t.id==='lang-select'){state.language=t.value;save();toast('Language preference updated')}if(t.id==='size-select'){state.textSize=t.value;save();render()}if(t.id==='motion'){state.reducedMotion=t.checked;save();document.documentElement.style.scrollBehavior=t.checked?'auto':'smooth'}if(t.id==='visibility'){state.visibility=t.checked;save();toast('Passport visibility updated')}if(t.id==='employer-visibility'){state.employerVisibility=t.checked;save();toast('Employer visibility updated')}if(t.id==='notify'){state.notify=t.checked;save();toast('Notification preference updated')}if(t.id==='mode-filter'||t.id==='category-filter'){filterCatalogue()}});
document.addEventListener('input',e=>{if(['global-search','catalog-search','job-search'].includes(e.target.id)){state.query=e.target.value;save();let pos=e.target.selectionStart;if(e.target.id==='global-search'){if(state.page==='programmes')render();else if(state.page==='jobs')render();}else if(state.page==='programmes'||state.page==='jobs')render();let n=$('#'+e.target.id);if(n){n.focus();n.setSelectionRange(pos,pos)}}if(e.target.id==='people-search'){document.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(e.target.value.toLowerCase())?'':'none')}if(e.target.id==='lesson-notes')localStorage.setItem('dakshya-notes',e.target.value)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='global-search'){let q=e.target.value.toLowerCase();state.query=e.target.value;state.page=/job|role|work|erp executive/.test(q)?'jobs':/certificate|credential/.test(q)?'certificates':/learner|trainee|rahul|anita/.test(q)?(state.role==='Employer'?'candidates':'profile'):'programmes';save();render()}});
function filterCatalogue(){let q=($('#catalog-search')?.value||'').toLowerCase(),m=$('#mode-filter')?.value,c=$('#category-filter')?.value;document.querySelectorAll('.course-card').forEach((el,i)=>{let p=programmes.filter(x=>`${x.title} ${x.cat} ${x.institute} ${x.mode}`.toLowerCase().includes((state.query||'').toLowerCase()))[i];el.style.display=p&&(!m||p.mode===m)&&(!c||p.cat===c)?'':'none'})}
render();
